with RecentInventory as (select * from inventory where store_id in (3, 5)), product_id_summary as (select product_id, date_format(last_restock, 'yyyy-MM') last_restock_month, sum(quantity) total_quantity from RecentInventory group by product_id, date_format(last_restock, 'yyyy-MM')) select product_id, last_restock_month, total_quantity from product_id_summary where total_quantity > 1120
